package selfupdate

import (
	"archive/zip"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path"
	"runtime"
	"strings"
	"time"
)

// sumsAsset is the checksum manifest generated by release.yml, covering all zip files in the Release.
const sumsAsset = "SHA256SUMS"

// maxBinarySize limits the size of the extracted binary to prevent a malformed zip from filling up the disk.
const maxBinarySize = 512 << 20 // 512 MiB

// Phase is the stage of the upgrade process, used directly as the phase field in SSE events.
type Phase string

const (
	PhaseIdle     Phase = "idle"
	PhaseDownload Phase = "downloading"
	PhaseVerify   Phase = "verifying"
	PhaseExtract  Phase = "extracting"
	PhaseStaged   Phase = "staged"
	PhaseFailed   Phase = "failed"
)

// Progress is provided by the caller and is used to push progress to the frontend. pct is only meaningful during the download stage (0-100),
// other stages pass -1.
type Progress func(ph Phase, pct int, msg string)

// Stage downloads the release package for the current platform from the specified Release, verifies it, and stages the new binary as artex.new.
//
// It uses the full zip rather than the bare binary, for two reasons: the existing Release's SHA256SUMS only covers the zip,
// so using the zip requires no CI changes and stays compatible with previously published historical versions; the zip also contains
// skills/ is kept so that built-in skills can be synced in the future. The only cost is downloading an extra few hundred KB for skills/.
//
// Returning from the function means staging is complete; the caller then shuts down gracefully and exits with ExitRestart.
func Stage(ctx context.Context, c *http.Client, rel *Release, currentVersion string, prog Progress) error {
	if prog == nil {
		prog = func(Phase, int, string) {}
	}
	p, err := ResolvePaths()
	if err != nil {
		return err
	}
	if err := checkWritable(p.Dir); err != nil {
		return err
	}

	name := AssetName(rel.TagName, runtime.GOOS, runtime.GOARCH)
	asset, ok := rel.FindAsset(name)
	if !ok {
		return fmt.Errorf("this version does not provide a release package for %s/%s (%s missing)", runtime.GOOS, runtime.GOARCH, name)
	}

	prog(PhaseDownload, 0, "fetching checksum list...")
	sums, err := fetchSums(ctx, c, rel)
	if err != nil {
		return err
	}
	want, ok := sums[name]
	if !ok {
		return fmt.Errorf("%s has no %s entry; refusing to install an unverified binary", sumsAsset, name)
	}

	// All temporary files are placed in the target directory, ensuring the final rename is an atomic operation within the same filesystem
	// (a cross-device rename would fail, and /tmp is often a separate mount point).
	zipPath := p.New + ".zip.part"
	binPath := p.New + ".part"
	defer func() {
		_ = os.Remove(zipPath)
		_ = os.Remove(binPath)
	}()

	prog(PhaseDownload, 0, fmt.Sprintf("downloading %s (%s)...", name, humanSize(asset.Size)))
	got, err := download(ctx, c, asset, zipPath, prog)
	if err != nil {
		return err
	}

	prog(PhaseVerify, -1, "verifying SHA256...")
	if !strings.EqualFold(got, want) {
		return fmt.Errorf("SHA256 does not match: expected %s, actual %s (download is corrupted or tampered)", short(want), short(got))
	}

	prog(PhaseExtract, -1, "extracting and running smoke test...")
	if err := extractBinary(zipPath, binPath); err != nil {
		return err
	}
	if err := smokeTest(binPath); err != nil {
		return fmt.Errorf("new version does not run on this system: %w", err)
	}

	// The staged file's sha256 is stored separately: it must be verified once more before swapping in on the next startup,
	// Prevents files from being modified or corrupted between staging and the restart.
	binSum, err := fileSHA256(binPath)
	if err != nil {
		return fmt.Errorf("failed to compute new binary checksum: %w", err)
	}
	if err := os.WriteFile(p.Sum, []byte(binSum), 0o644); err != nil {
		return fmt.Errorf("failed to record checksum: %w", err)
	}
	if err := os.Rename(binPath, p.New); err != nil {
		_ = os.Remove(p.Sum)
		return fmt.Errorf("failed to prepare new version: %w", err)
	}

	if err := writeMarker(p.Marker, marker{
		From:     currentVersion,
		To:       strings.TrimPrefix(rel.TagName, "v"),
		StagedAt: time.Now().Unix(),
	}); err != nil {
		// The flag only affects automatic rollback capability; the staged file is already in place, so this does not interrupt the upgrade.
		prog(PhaseStaged, -1, "warning: failed to write the update marker file, so this update will not get automatic rollback protection")
	}

	prog(PhaseStaged, 100, "New version is ready. Restarting...")
	return nil
}

// fetchSums downloads and parses SHA256SUMS, returning a map of filename → hex digest.
func fetchSums(ctx context.Context, c *http.Client, rel *Release) (map[string]string, error) {
	asset, ok := rel.FindAsset(sumsAsset)
	if !ok {
		return nil, fmt.Errorf("this release has no %s entry, so integrity cannot be verified; refusing the update", sumsAsset)
	}
	body, err := get(ctx, c, asset.URL)
	if err != nil {
		return nil, fmt.Errorf("failed to download %s: %w", sumsAsset, err)
	}
	defer body.Close()

	raw, err := io.ReadAll(io.LimitReader(body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("failed to read %s: %w", sumsAsset, err)
	}
	out := parseSums(string(raw))
	if len(out) == 0 {
		return nil, fmt.Errorf("%s is empty or its format is not recognized", sumsAsset)
	}
	return out, nil
}

// parseSums parses a manifest in sha256sum style and returns a map of file name → hex digest.
//
// A line is only recorded if its first field is a 64-character hex string. Checking only that there are exactly two fields is not enough——
// otherwise any line with two words of descriptive text would be accepted as a valid entry, injecting garbage values into the digest table,
// and a real asset could end up matching the wrong digest.
func parseSums(raw string) map[string]string {
	out := map[string]string{}
	for line := range strings.Lines(raw) {
		// The format is "<sha256>  <filename>" (sha256sum uses two spaces; shasum's binary
		// the pattern prepends a * to the file name).
		fields := strings.Fields(strings.TrimSpace(line))
		if len(fields) != 2 || !isHexSHA256(fields[0]) {
			continue
		}
		name := strings.TrimPrefix(fields[1], "*")
		if name == "" {
			continue
		}
		out[name] = strings.ToLower(fields[0])
	}
	return out
}

func isHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
		default:
			return false
		}
	}
	return true
}

// download writes the asset to dst, computes the SHA256 while doing so, and reports progress based on Content-Length.
func download(ctx context.Context, c *http.Client, a Asset, dst string, prog Progress) (string, error) {
	body, err := get(ctx, c, a.URL)
	if err != nil {
		return "", fmt.Errorf("failed to download %s: %w", a.Name, err)
	}
	defer body.Close()

	f, err := os.Create(dst)
	if err != nil {
		return "", fmt.Errorf("failed to create temporary file: %w", err)
	}
	defer f.Close()

	h := sha256.New()
	pw := &progressWriter{total: a.Size, prog: prog, name: a.Name, last: time.Now()}
	if _, err := io.Copy(io.MultiWriter(f, h, pw), body); err != nil {
		return "", fmt.Errorf("download interrupted: %w", err)
	}
	if err := f.Sync(); err != nil {
		return "", fmt.Errorf("disk write failed: %w", err)
	}
	if a.Size > 0 && pw.written != a.Size {
		return "", fmt.Errorf("download incomplete: expected %d bytes, actual %d bytes", a.Size, pw.written)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// get issues a GET request constrained by an allowlist and returns the response body.
func get(ctx context.Context, c *http.Client, rawURL string) (io.ReadCloser, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, err
	}
	if err := checkURL(req.URL); err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "artex-selfupdate")
	resp, err := c.Do(req)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		resp.Body.Close()
		return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
	}
	return resp.Body, nil
}

// extractBinary pulls the artex executable out of the release archive.
//
// The archive layout is artex-<version>-<os>-<arch>/artex, but here we match on the **base name** instead of building the full
// path: the version number appears once in the package name, so a single mistyped character would fail the whole upgrade; matching by base name is more tolerant of change.
func extractBinary(zipPath, dst string) error {
	want := "artex"
	if runtime.GOOS == "windows" {
		want = "artex.exe"
	}
	zr, err := zip.OpenReader(zipPath)
	if err != nil {
		return fmt.Errorf("failed to open release package: %w", err)
	}
	defer zr.Close()

	for _, entry := range zr.File {
		if entry.FileInfo().IsDir() || !strings.EqualFold(path.Base(entry.Name), want) {
			continue
		}
		rc, err := entry.Open()
		if err != nil {
			return fmt.Errorf("failed to read %s: %w", entry.Name, err)
		}
		defer rc.Close()

		f, err := os.OpenFile(dst, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755)
		if err != nil {
			return fmt.Errorf("failed to write new binary: %w", err)
		}
		defer f.Close()

		n, err := io.Copy(f, io.LimitReader(rc, maxBinarySize+1))
		if err != nil {
			return fmt.Errorf("failed to decompress %s: %w", entry.Name, err)
		}
		if n > maxBinarySize {
			return fmt.Errorf("executable inside release package is larger than %s; refusing to decompress", humanSize(maxBinarySize))
		}
		if n == 0 {
			return fmt.Errorf("%s file inside release package is empty", want)
		}
		return f.Sync()
	}
	return fmt.Errorf("could not find %s file in release package", want)
}

// checkWritable confirms up front that the directory is writable. Without this step, running as non-root, or placing the binary in a system
// directory would only fail at the moment of swapping in the new binary, after tens of MB have already been downloaded.
func checkWritable(dir string) error {
	probe, err := os.CreateTemp(dir, ".artex-update-probe-*")
	if err != nil {
		return fmt.Errorf("cannot write to program directory %s; automatic update is not possible (check permissions or use a manual update): %w", dir, err)
	}
	name := probe.Name()
	_ = probe.Close()
	_ = os.Remove(name)
	return nil
}

// progressWriter tracks the number of bytes written and rate-limits progress reports, so that a push is not sent over SSE for every 32KiB chunk.
type progressWriter struct {
	total   int64
	written int64
	name    string
	prog    Progress
	last    time.Time
}

func (w *progressWriter) Write(b []byte) (int, error) {
	w.written += int64(len(b))
	if time.Since(w.last) < 300*time.Millisecond {
		return len(b), nil
	}
	w.last = time.Now()
	pct := -1
	if w.total > 0 {
		pct = int(w.written * 100 / w.total)
	}
	w.prog(PhaseDownload, pct, fmt.Sprintf("downloading %s / %s", humanSize(w.written), humanSize(w.total)))
	return len(b), nil
}

func humanSize(n int64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}
	div, exp := int64(unit), 0
	for v := n / unit; v >= unit; v /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %cB", float64(n)/float64(div), "KMGT"[exp])
}

func short(sum string) string {
	if len(sum) > 12 {
		return sum[:12] + "…"
	}
	return sum
}
